 BEGIN; 
 CREATE OR REPLACE FUNCTION public.get_destinatarios_area_nivel(IN p_id_empresa integer,IN p_codigo_area text,IN p_nivel_jerarquico text)
    RETURNS TABLE(id_puesto bigint, puesto_nombre text, id_empleado bigint, empleado text, id_usuario bigint, correo_institucional text)
    LANGUAGE 'sql'
    STABLE
    PARALLEL UNSAFE
    COST 100    ROWS 1000 
    
AS $BODY$
    SELECT DISTINCT
        puesto.id AS id_puesto,
        TRIM(puesto.puesto_nombre)::text AS puesto_nombre,
        empleado.id AS id_empleado,
        NULLIF(
            TRIM(CONCAT_WS(
                ' ',
                empleado.nombres,
                empleado.apellido_paterno,
                empleado.apellido_materno
            )),
            ''
        )::text AS empleado,
        usuario.id AS id_usuario,
        LOWER(TRIM(empleado.correo_institucional))::text AS correo_institucional
    FROM public.cat_areas area
    INNER JOIN public.cat_puestos puesto
        ON UPPER(TRIM(puesto.area_codigo)) = UPPER(TRIM(area.codigo_area))
    INNER JOIN public.cat_empleados empleado
        ON empleado.id_puesto = puesto.id
       AND empleado.id_empresa = p_id_empresa
       AND COALESCE(empleado.enable, TRUE) = TRUE
    LEFT JOIN public.cat_usuarios usuario
        ON usuario.id_empleado = empleado.id
       AND usuario.id_empresa = empleado.id_empresa
    WHERE UPPER(TRIM(area.codigo_area)) = UPPER(TRIM(p_codigo_area))
      AND area.id_empresas @> jsonb_build_array(p_id_empresa)
      AND puesto.id_empresas @> jsonb_build_array(p_id_empresa)
      AND COALESCE(area.enable, TRUE) = TRUE
      AND COALESCE(puesto.enable, TRUE) = TRUE
      AND puesto.nivel_jerarquico::text = TRIM(p_nivel_jerarquico)
      AND NULLIF(TRIM(empleado.correo_institucional), '') IS NOT NULL
      AND (
          usuario.id IS NULL
          OR (
              COALESCE(usuario.enable, TRUE) = TRUE
              AND COALESCE(usuario.estatus_usuario, TRUE) = TRUE
          )
      );
$BODY$;

COMMENT ON FUNCTION public.get_destinatarios_area_nivel(integer, text, text)
    IS 'Devuelve puestos, empleados, usuarios y correos institucionales activos por empresa, area y nivel jerarquico.';
CREATE OR REPLACE FUNCTION public.fn_reporte_ventas(IN p_id_empresa integer,IN p_fecha_inicio date,IN p_fecha_fin date,IN p_busqueda text,IN p_filtros jsonb,IN p_orden text,IN p_direccion text,IN p_limite integer,IN p_offset integer)
    RETURNS TABLE(total integer, rows jsonb)
    LANGUAGE 'plpgsql'
    STABLE
    PARALLEL UNSAFE
    COST 100    ROWS 1000 
    
AS $BODY$
DECLARE
  v_columnas constant text[] := ARRAY['cantidad', 'fecha', 'importe', 'precio_unitario', 'producto', 'folio', 'unidad_medida', 'vendedor', 'empresa', 'sucursal', 'cliente', 'forma_pago', 'promocion', 'promocion_registrada', 'descuento', 'importe_neto', 'descuento_origen_label', 'descuento_motivo'];
  v_orden text := CASE WHEN p_orden = ANY(v_columnas) THEN p_orden ELSE 'fecha' END;
  v_direccion text := CASE WHEN p_direccion = 'asc' THEN 'ASC' ELSE 'DESC' END;
  v_filtro jsonb;
  v_columna text;
  v_filtros text := '';
BEGIN
  -- Solo se interpolan columnas de la lista permitida y literales escapados por format.
  FOR v_filtro IN SELECT value FROM jsonb_array_elements(COALESCE(p_filtros, '[]'::jsonb)) LOOP
    v_columna := v_filtro->>'columna';
    IF NOT COALESCE(v_columna = ANY(v_columnas), false) THEN CONTINUE; END IF;
    IF v_columna = 'fecha' THEN
      IF NULLIF(v_filtro->>'desde', '') IS NOT NULL THEN
        v_filtros := v_filtros || format(' AND b.fecha >= (%L::date::timestamp AT TIME ZONE ''America/Mexico_City'')', v_filtro->>'desde');
      END IF;
      IF NULLIF(v_filtro->>'hasta', '') IS NOT NULL THEN
        v_filtros := v_filtros || format(' AND b.fecha < ((%L::date + 1)::timestamp AT TIME ZONE ''America/Mexico_City'')', v_filtro->>'hasta');
      END IF;
    ELSE
      v_filtros := v_filtros || format(' AND translate(lower(COALESCE(b.%I::text, '''')), ''áéíóúüñ'', ''aeiouun'') LIKE %L', v_columna, v_filtro->>'patron');
    END IF;
  END LOOP;
  RETURN QUERY EXECUTE format($consulta$
WITH partidas AS (
      SELECT dc.id, dc.id_cuenta,
        COALESCE(dc.promocion_monto, 0) AS promocion_registrada,
        GREATEST(COALESCE(dc.importe_linea, 0), 0) AS importe,
        GREATEST(COALESCE(c.total, 0), 0) AS total_guardado,
        GREATEST(COALESCE(c.descuento_monto, 0), 0) AS descuento_cuenta
      FROM public.detalle_cuenta dc
      JOIN public.cuenta c ON c.id = dc.id_cuenta AND c.id_empresa = dc.id_empresa
      WHERE c.id_empresa = $1::int AND c.id_estado = 3 AND dc.enable = 1
        AND c.fecha_registro >= ($2::date::timestamp AT TIME ZONE 'America/Mexico_City')
        AND c.fecha_registro < (($3::date + 1)::timestamp AT TIME ZONE 'America/Mexico_City')
    ), totales AS (
      SELECT *,
        SUM(importe) OVER (PARTITION BY id_cuenta) AS importe_cuenta,
        SUM(GREATEST(importe - promocion_registrada, 0)) OVER (PARTITION BY id_cuenta) AS importe_sin_promocion_cuenta
      FROM partidas
    ), promociones AS (
      SELECT *,
        -- Hay cuentas históricas donde importe_linea ya incluye la promoción
        -- y otras donde todavía debe restarse. Se usa la variante que mejor
        -- coincide con el total histórico guardado de la cuenta.
        CASE WHEN ABS(ROUND(total_guardado, 2) - ROUND(importe_cuenta, 2))
          <= ABS(ROUND(total_guardado, 2) - ROUND(importe_sin_promocion_cuenta, 2))
          THEN 0::numeric ELSE promocion_registrada END AS promocion
      FROM totales
    ), bases AS (
      SELECT *, GREATEST(importe - promocion, 0) AS base_neta
      FROM promociones
    ), acumulados AS (
      SELECT *,
        SUM(base_neta) OVER (PARTITION BY id_cuenta) AS base_cuenta,
        SUM(base_neta) OVER (PARTITION BY id_cuenta ORDER BY id ROWS UNBOUNDED PRECEDING) AS acumulado,
        ROW_NUMBER() OVER (PARTITION BY id_cuenta ORDER BY id) AS posicion
      FROM bases
    ), descuentos AS (
      SELECT id, promocion, promocion_registrada, base_neta,
        CASE WHEN base_cuenta > 0 THEN
          ROUND(descuento_cuenta * acumulado / base_cuenta, 2)
          - ROUND(descuento_cuenta * (acumulado - base_neta) / base_cuenta, 2)
        WHEN posicion = 1 THEN descuento_cuenta ELSE 0 END AS descuento
      FROM acumulados
    ), base AS NOT MATERIALIZED (
      SELECT dc.id, c.id AS id_cuenta, c.id_empresa, c.folio_cuenta AS folio,
        c.fecha_registro AS fecha, c.id_estado, dc.enable,
        dc.cantidad, COALESCE(NULLIF(trim(dc.unidad_medida), ''),
          NULLIF(trim(unidad.abreviatura), ''), NULLIF(trim(unidad.nombre), ''), 'Sin unidad registrada') AS unidad_medida,
        dc.precio_unitario,
        dc.importe_linea AS importe, dc.nombre_producto AS producto,
        descuentos.promocion, descuentos.promocion_registrada, descuentos.descuento,
        descuentos.base_neta - descuentos.descuento AS importe_neto,
        (COALESCE(c.descuento_autorizado, false) AND COALESCE(c.descuento_monto, 0) > 0) AS descuento_autorizado,
        (descuentos.promocion_registrada > 0) AS descuento_por_oferta,
        COALESCE(NULLIF(CONCAT_WS(' / ',
          CASE WHEN COALESCE(c.descuento_autorizado, false) AND COALESCE(c.descuento_monto, 0) > 0
            THEN 'Autorizado' END,
          CASE WHEN descuentos.promocion_registrada > 0 THEN 'Oferta' END), ''),
          'Sin descuento') AS descuento_origen_label,
        CASE WHEN COALESCE(c.descuento_autorizado, false) AND COALESCE(c.descuento_monto, 0) > 0
          THEN NULLIF(TRIM(c.descuento_motivo), '') END AS descuento_motivo,
        COALESCE(NULLIF(trim(c.nombre_mesero), ''), 'Sin vendedor registrado') AS vendedor,
        COALESCE(NULLIF(e.nombre_comercial, ''), e.razon_social) AS empresa,
        COALESCE(NULLIF(dc.nombre_comensal, ''), comensal.nombre, 'Público en general') AS cliente,
        COALESCE(est.nombre_corto, est.nombre_completo, 'Sin sucursal') AS sucursal,
        c.metodo_pago_codigo, c.metodo_pago, c.pago_mixto, c.descuento_monto,
        pagos.metodos AS pagos_divididos,
        COALESCE(NULLIF(array_to_string(ARRAY(
          SELECT label FROM (VALUES ('0', 'Efectivo'), ('1', 'Tarjeta de débito'),
            ('2', 'Tarjeta de crédito'), ('3', 'Transferencia')) AS methods(code, label)
          WHERE code IN (
            SELECT c.metodo_pago_codigo::text
            UNION SELECT value #>> '{}' FROM jsonb_path_query(
              jsonb_build_array(c.metodo_pago, c.pago_mixto, pagos.metodos), '$.**.codigo') AS value
            UNION SELECT value #>> '{}' FROM jsonb_path_query(
              jsonb_build_array(c.metodo_pago, c.pago_mixto, pagos.metodos), '$.**.metodo_pago_codigo') AS value
          ) ORDER BY code
        ), ' / '), ''), CASE WHEN c.metodo_pago_codigo = 4 THEN 'Mixto'
          WHEN c.descuento_monto > 0 THEN 'Descuento' ELSE 'Sin pago registrado' END) AS forma_pago
      FROM public.detalle_cuenta dc
      JOIN public.cuenta c ON c.id = dc.id_cuenta AND c.id_empresa = dc.id_empresa
      JOIN descuentos ON descuentos.id = dc.id
      LEFT JOIN public.cat_empresa e ON e.id = c.id_empresa
      LEFT JOIN public.cat_productos producto ON producto.id = dc.id_producto AND producto.id_empresa = dc.id_empresa
      LEFT JOIN LATERAL (
        SELECT u.abreviatura, u.nombre FROM public.cat_unidades_medida u
        WHERE u.id_empresa = producto.id_empresa AND (
          u.id::text = trim(producto.id_unidad) OR upper(u.codigo) = upper(trim(producto.id_unidad))
          OR upper(u.clave_sat) = upper(trim(producto.id_unidad))
          OR upper(u.nombre) = upper(trim(producto.id_unidad))
          OR upper(u.abreviatura) = upper(trim(producto.id_unidad))
          OR u.id_unidad_medida_sat = producto.id_unidad_medida)
        ORDER BY CASE WHEN u.id::text = trim(producto.id_unidad) THEN 0 ELSE 1 END, u.id
        LIMIT 1
      ) unidad ON true
      LEFT JOIN public.cat_establecimientos est ON est.id = c.id_establecimiento AND est.id_empresa = c.id_empresa
      LEFT JOIN LATERAL (
        SELECT NULLIF(om.nombre_comensal, '') AS nombre FROM public.ocupacion_mesa om
        WHERE om.id_cuenta = c.id ORDER BY om.id DESC LIMIT 1
      ) comensal ON true
      LEFT JOIN LATERAL (
        SELECT jsonb_agg(cd.metodo_pago ORDER BY cd.id) AS metodos
        FROM public.cuenta_division cd WHERE cd.id_cuenta = c.id AND cd.estado = 'pagado'
      ) pagos ON true
      WHERE c.id_empresa = $1::int AND dc.id_empresa = c.id_empresa AND c.id_estado = 3 AND dc.enable = 1
        AND c.fecha_registro >= ($2::date::timestamp AT TIME ZONE 'America/Mexico_City')
        AND c.fecha_registro < (($3::date + 1)::timestamp AT TIME ZONE 'America/Mexico_City')
        AND ($4::text IS NULL OR dc.nombre_producto ILIKE $4 OR c.folio_cuenta ILIKE $4)
    ), filtrados AS MATERIALIZED (
      SELECT b.id, b.%1$I AS orden FROM base b WHERE TRUE %3$s
    ), pagina AS (
      SELECT id, orden FROM filtrados ORDER BY orden %2$s NULLS LAST, id DESC
      LIMIT $8::int OFFSET $9::int
    ), filas AS (
      SELECT b.* FROM pagina p JOIN base b ON b.id = p.id
    ) SELECT (SELECT count(*)::int FROM filtrados) AS total,
      COALESCE((SELECT jsonb_agg(f ORDER BY f.%1$I %2$s NULLS LAST, f.id DESC) FROM filas f), '[]'::jsonb) AS rows
$consulta$, v_orden, v_direccion, v_filtros)
  USING p_id_empresa, p_fecha_inicio, p_fecha_fin, p_busqueda, p_filtros, p_orden, p_direccion, p_limite, p_offset;
END;
$BODY$;
CREATE OR REPLACE FUNCTION public.guardar_produccion_despiece(IN p_empresa integer,IN p_usuario integer,IN p_id integer,IN p_version integer,IN p_data jsonb)
    RETURNS TABLE(id integer, version integer)
    LANGUAGE 'plpgsql'
    VOLATILE
    PARALLEL UNSAFE
    COST 100    ROWS 1000 
    
AS $BODY$
DECLARE
  v_id integer;
  v_version integer;
  v_entrada integer;
  v_estado text;
  v_variante text;
  v_merma numeric;
  v_productos jsonb;
  v_ids integer[];
  v_decimal constant text := '^[0-9]{1,8}(\.[0-9]{1,4})?$';
BEGIN
  IF p_empresa IS DISTINCT FROM 1 OR p_usuario IS NULL THEN
    RAISE EXCEPTION 'La empresa o el usuario no son válidos';
  END IF;
  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' THEN
    RAISE EXCEPTION 'Los datos del despiece no son válidos';
  END IF;
  IF coalesce(p_data->>'tipo_proceso', 'DESPIECE') <> 'DESPIECE' THEN
    RAISE EXCEPTION 'Esta configuración solo admite Despiece';
  END IF;
  v_estado := coalesce(p_data->>'estado', 'BORRADOR');
  IF v_estado NOT IN ('BORRADOR', 'ACTIVA', 'INACTIVA') THEN
    RAISE EXCEPTION 'El estado del despiece no es válido';
  END IF;
  v_variante := btrim(coalesce(p_data->>'variante', 'Estándar'));
  IF v_variante = '' OR char_length(v_variante) > 80 THEN
    RAISE EXCEPTION 'El nombre de la variante debe tener entre 1 y 80 caracteres';
  END IF;
  IF jsonb_typeof(p_data->'disponible_cedis') IS DISTINCT FROM 'boolean' OR
    jsonb_typeof(p_data->'disponible_sucursales') IS DISTINCT FROM 'boolean' THEN
    RAISE EXCEPTION 'La disponibilidad debe contener valores booleanos';
  END IF;
  IF NOT ((p_data->>'disponible_cedis')::boolean OR (p_data->>'disponible_sucursales')::boolean) THEN
    RAISE EXCEPTION 'Selecciona al menos una ubicación disponible';
  END IF;

  IF jsonb_typeof(p_data->'rendimiento_merma') IN ('number', 'string') THEN
    IF (p_data->>'rendimiento_merma') !~ v_decimal THEN
      RAISE EXCEPTION 'El rendimiento de merma admite hasta 4 decimales';
    END IF;
    v_merma := (p_data->>'rendimiento_merma')::numeric;
  ELSE
    RAISE EXCEPTION 'Captura el rendimiento de merma del despiece';
  END IF;

  v_productos := coalesce(p_data->'productos', '[]'::jsonb);
  IF jsonb_typeof(v_productos) <> 'array' THEN RAISE EXCEPTION 'El despiece debe incluir un arreglo de productos'; END IF;
  IF jsonb_array_length(v_productos) > 200 THEN RAISE EXCEPTION 'El despiece admite hasta 200 productos obtenidos'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_productos) p WHERE
    coalesce(p->>'id_producto', '') !~ '^[0-9]+$' OR
    (p->>'rendimiento_directo' IS NOT NULL AND (p->>'rendimiento_directo') !~ v_decimal) OR
    (p->>'rendimiento_inverso' IS NOT NULL AND (p->>'rendimiento_inverso') !~ v_decimal)) THEN
    RAISE EXCEPTION 'Cada rendimiento admite hasta 4 decimales';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_productos) p WHERE
    (p->>'rendimiento_directo')::numeric <= 0 OR (p->>'rendimiento_inverso')::numeric <= 0) THEN
    RAISE EXCEPTION 'Los rendimientos deben ser mayores a cero';
  END IF;

  v_entrada := (p_data->>'id_producto_entrada')::integer;
  IF v_entrada IS NULL OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_productos) p WHERE (p->>'id_producto')::integer = v_entrada) THEN
    RAISE EXCEPTION 'El producto de entrada no puede repetirse como producto obtenido';
  END IF;
  IF (SELECT count(DISTINCT (p->>'id_producto')::integer) FROM jsonb_array_elements(v_productos) p) <> jsonb_array_length(v_productos) THEN
    RAISE EXCEPTION 'No se permiten productos obtenidos repetidos';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.produccion_despieces d
    WHERE d.id_empresa = p_empresa AND d.id_producto_entrada = v_entrada
      AND lower(btrim(d.variante)) = lower(v_variante) AND d.id IS DISTINCT FROM p_id
  ) THEN
    RAISE EXCEPTION 'Ya existe una variante con ese nombre para este producto de entrada';
  END IF;

  IF v_estado = 'ACTIVA' THEN
    IF jsonb_array_length(v_productos) = 0 THEN
      RAISE EXCEPTION 'Agrega al menos un producto obtenido para activar el despiece';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_productos) p WHERE p->>'rendimiento_directo' IS NULL) THEN
      RAISE EXCEPTION 'Captura el rendimiento directo de cada producto obtenido para activar el despiece';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_productos) p WHERE p->>'rendimiento_inverso' IS NULL) THEN
      RAISE EXCEPTION 'Captura el rendimiento inverso de cada producto obtenido para activar el despiece';
    END IF;
  END IF;

  SELECT array_agg(DISTINCT product_id) INTO v_ids FROM (
    SELECT v_entrada AS product_id UNION ALL SELECT (p->>'id_producto')::integer FROM jsonb_array_elements(v_productos) p
  ) productos;
  PERFORM 1 FROM public.cat_productos p WHERE p.id_empresa = p_empresa AND p.id = ANY(v_ids) ORDER BY p.id FOR SHARE;
  IF (SELECT count(*) FROM public.produccion_batida_productos_kg p WHERE p.id_empresa = p_empresa AND p.id = ANY(v_ids)) <> cardinality(v_ids) THEN
    RAISE EXCEPTION 'Cada producto debe estar activo, pertenecer a la empresa y tener unidad kg';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.produccion_despieces AS d
      (id_empresa, id_producto_entrada, variante, disponible_cedis, disponible_sucursales, estado, rendimiento_merma, creado_por, modificado_por)
    VALUES (p_empresa, v_entrada, v_variante, (p_data->>'disponible_cedis')::boolean,
      (p_data->>'disponible_sucursales')::boolean, v_estado, v_merma, p_usuario, p_usuario)
    RETURNING d.id, d.version INTO v_id, v_version;
  ELSE
    UPDATE public.produccion_despieces d SET id_producto_entrada = v_entrada, variante = v_variante,
      disponible_cedis = (p_data->>'disponible_cedis')::boolean,
      disponible_sucursales = (p_data->>'disponible_sucursales')::boolean,
      estado = v_estado, rendimiento_merma = v_merma,
      modificado_por = p_usuario, fecha_modificacion = now(), version = d.version + 1
    WHERE d.id = p_id AND d.id_empresa = p_empresa AND d.version = p_version
    RETURNING d.id, d.version INTO v_id, v_version;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'El despiece cambió o ya no está disponible. Vuelve a abrirlo antes de guardar' USING ERRCODE = '40001';
    END IF;
    DELETE FROM public.produccion_despiece_productos p WHERE p.id_despiece = v_id AND p.id_empresa = p_empresa;
  END IF;

  INSERT INTO public.produccion_despiece_productos
    (id_empresa, id_despiece, id_producto, rendimiento_directo, rendimiento_inverso, orden)
  SELECT p_empresa, v_id, (p.value->>'id_producto')::integer,
    (p.value->>'rendimiento_directo')::numeric, (p.value->>'rendimiento_inverso')::numeric, p.ordinality::integer
  FROM jsonb_array_elements(v_productos) WITH ORDINALITY p(value, ordinality);
  RETURN QUERY SELECT v_id, v_version;
END;
$BODY$;
CREATE OR REPLACE FUNCTION public.fn_eliminar_borrador_solicitud_traspaso(IN p_id_solicitud bigint,IN p_id_empresa integer,IN p_id_usuario integer)
    RETURNS boolean
    LANGUAGE 'plpgsql'
    VOLATILE
    PARALLEL UNSAFE
    COST 100
    
AS $BODY$
DECLARE
    v_id_sucursal INTEGER;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.cat_usuarios u
        WHERE u.id = p_id_usuario
          AND u.id_empresa = p_id_empresa
          AND u.enable = TRUE
    ) THEN
        RAISE EXCEPTION 'El usuario no esta activo o pertenece a otra empresa';
    END IF;

    SELECT st.id_sucursal_solicitante INTO v_id_sucursal
    FROM public.solicitudes_traspaso st
    WHERE st.id_solicitud = p_id_solicitud
      AND st.id_empresa = p_id_empresa
      AND st.creado_por = p_id_usuario
      AND st.estatus = 'Borrador'
    FOR UPDATE;

    IF v_id_sucursal IS NULL THEN
        RAISE EXCEPTION 'El borrador no existe o no pertenece al usuario';
    END IF;

    DELETE FROM public.solicitud_traspaso_detalle
    WHERE id_empresa = p_id_empresa
      AND id_solicitud IN (
          SELECT st.id_solicitud
          FROM public.solicitudes_traspaso st
          WHERE st.id_empresa = p_id_empresa
            AND st.creado_por = p_id_usuario
            AND st.id_sucursal_solicitante = v_id_sucursal
            AND st.estatus = 'Borrador'
      );

    DELETE FROM public.solicitudes_traspaso
    WHERE id_empresa = p_id_empresa
      AND creado_por = p_id_usuario
      AND id_sucursal_solicitante = v_id_sucursal
      AND estatus = 'Borrador';

    RETURN TRUE;
END;
$BODY$;
CREATE OR REPLACE FUNCTION public.fn_enviar_solicitud_traspaso(IN p_id_solicitud bigint,IN p_id_empresa integer,IN p_id_usuario integer)
    RETURNS TABLE(solicitud_id bigint, solicitud_folio character varying, solicitud_estatus character varying)
    LANGUAGE 'plpgsql'
    VOLATILE
    PARALLEL UNSAFE
    COST 100    ROWS 1000 
    
AS $BODY$
DECLARE
    v_solicitud public.solicitudes_traspaso%ROWTYPE;
    v_folio VARCHAR(40);
BEGIN
    SELECT * INTO v_solicitud
    FROM public.solicitudes_traspaso st
    WHERE st.id_solicitud = p_id_solicitud AND st.id_empresa = p_id_empresa
    FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'La solicitud no existe'; END IF;
    IF v_solicitud.estatus <> 'Borrador' THEN
        RAISE EXCEPTION 'Solo se pueden enviar solicitudes en borrador';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.cat_usuarios u
        WHERE u.id = p_id_usuario AND u.id_empresa = p_id_empresa AND u.enable = TRUE
    ) THEN
        RAISE EXCEPTION 'El usuario no esta activo o pertenece a otra empresa';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.solicitud_traspaso_detalle d
        WHERE d.id_solicitud = p_id_solicitud AND d.id_empresa = p_id_empresa
    ) THEN
        RAISE EXCEPTION 'No se puede enviar una solicitud sin productos';
    END IF;

    v_folio := public.fn_traspaso_generar_folio(
        'ST', p_id_empresa, v_solicitud.id_sucursal_solicitante
    );

    UPDATE public.solicitudes_traspaso
    SET folio = v_folio, estatus = 'Enviada', fecha_envio = NOW(),
        actualizado_por = p_id_usuario, fecha_actualizacion = NOW()
    WHERE id_solicitud = p_id_solicitud;

    RETURN QUERY SELECT st.id_solicitud, st.folio, st.estatus
    FROM public.solicitudes_traspaso st WHERE st.id_solicitud = p_id_solicitud;
END;
$BODY$;

 END;


 -- only source
 -- This script was generated by the Schema Diff utility in pgAdmin 4. 
-- Due to circular dependencies, the order in which Schema Diff writes objects may not be optimal 
-- and manual changes to the script may be required to ensure changes are applied in the correct order.
-- Please report any issues along with steps to reproduce. 
 BEGIN; 
 CREATE OR REPLACE FUNCTION public.fn_guardar_borrador_solicitud_traspaso(
	p_id_solicitud bigint,
	p_id_empresa integer,
	p_id_usuario integer,
	p_id_sucursal integer,
	p_motivo character varying,
	p_fecha_requerida date,
	p_productos jsonb,
	p_id_tipo_traspaso integer)
    RETURNS TABLE(solicitud_id bigint, solicitud_estatus character varying) 
    LANGUAGE 'plpgsql'
    COST 100
    VOLATILE PARALLEL UNSAFE
    ROWS 1000

AS $BODY$

DECLARE
    v_id_solicitud BIGINT;
    v_id_tipo_traspaso INTEGER;
BEGIN
    IF p_id_empresa IS NULL OR p_id_empresa <= 0 THEN
        RAISE EXCEPTION 'id_empresa es requerido';
    END IF;
    IF NULLIF(BTRIM(p_motivo), '') IS NULL OR LENGTH(BTRIM(p_motivo)) > 250 THEN
        RAISE EXCEPTION 'El motivo es requerido y no puede exceder 250 caracteres';
    END IF;
    IF p_fecha_requerida IS NULL OR p_fecha_requerida < CURRENT_DATE THEN
        RAISE EXCEPTION 'La fecha requerida debe ser igual o posterior a la fecha actual';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.cat_usuarios u
        WHERE u.id = p_id_usuario AND u.id_empresa = p_id_empresa AND u.enable = TRUE
    ) THEN
        RAISE EXCEPTION 'El usuario no esta activo o pertenece a otra empresa';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM public.cat_establecimientos e
        WHERE e.id = p_id_sucursal AND e.id_empresa = p_id_empresa AND e.enable = TRUE
    ) THEN
        RAISE EXCEPTION 'La sucursal no esta activa o pertenece a otra empresa';
    END IF;

    SELECT tt.id INTO v_id_tipo_traspaso
    FROM public.cat_tipos_traspaso tt
    WHERE tt.id = p_id_tipo_traspaso
      AND tt.enable = TRUE;

    IF v_id_tipo_traspaso IS NULL THEN
        RAISE EXCEPTION 'El tipo de traspaso es requerido, no existe o esta inactivo';
    END IF;
    IF p_productos IS NULL OR jsonb_typeof(p_productos) <> 'array'
       OR jsonb_array_length(p_productos) = 0 THEN
        RAISE EXCEPTION 'Agrega al menos un producto al borrador';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_productos) AS item(id_producto INTEGER, cantidad NUMERIC)
        WHERE item.id_producto IS NULL OR item.id_producto <= 0
           OR item.cantidad IS NULL OR item.cantidad <= 0
    ) THEN
        RAISE EXCEPTION 'Todos los productos deben tener una cantidad positiva';
    END IF;
    IF (
        SELECT COUNT(*) FROM jsonb_to_recordset(p_productos)
            AS item(id_producto INTEGER, cantidad NUMERIC)
    ) <> (
        SELECT COUNT(DISTINCT item.id_producto)
        FROM jsonb_to_recordset(p_productos)
            AS item(id_producto INTEGER, cantidad NUMERIC)
    ) THEN
        RAISE EXCEPTION 'No se permiten productos duplicados';
    END IF;

    -- Evita que dos guardados simultaneos creen dos borradores para el mismo
    -- usuario, empresa y sucursal.
    PERFORM pg_advisory_xact_lock(
        hashtext('traspaso-borrador'),
        hashtext(p_id_empresa::TEXT || ':' || p_id_usuario::TEXT || ':' || p_id_sucursal::TEXT)
    );

    IF p_id_solicitud IS NULL THEN
        SELECT st.id_solicitud INTO v_id_solicitud
        FROM public.solicitudes_traspaso st
        WHERE st.id_empresa = p_id_empresa
          AND st.creado_por = p_id_usuario
          AND st.id_sucursal_solicitante = p_id_sucursal
          AND st.estatus = 'Borrador'
        ORDER BY COALESCE(st.fecha_actualizacion, st.fecha_creacion) DESC,
                 st.id_solicitud DESC
        LIMIT 1
        FOR UPDATE;
    ELSE
        SELECT st.id_solicitud INTO v_id_solicitud
        FROM public.solicitudes_traspaso st
        WHERE st.id_solicitud = p_id_solicitud
          AND st.id_empresa = p_id_empresa
          AND st.creado_por = p_id_usuario
          AND st.id_sucursal_solicitante = p_id_sucursal
          AND st.estatus = 'Borrador'
        FOR UPDATE;

        IF v_id_solicitud IS NULL THEN
            RAISE EXCEPTION 'El borrador no existe o ya no se puede editar';
        END IF;
    END IF;

    IF v_id_solicitud IS NULL THEN
        INSERT INTO public.solicitudes_traspaso (
            id_empresa, id_tipo_traspaso, folio, id_sucursal_solicitante, motivo,
            fecha_requerida, estatus, creado_por
        ) VALUES (
            p_id_empresa, v_id_tipo_traspaso, NULL, p_id_sucursal, BTRIM(p_motivo),
            p_fecha_requerida, 'Borrador', p_id_usuario
        ) RETURNING id_solicitud INTO v_id_solicitud;
    ELSE
        UPDATE public.solicitudes_traspaso
        SET id_tipo_traspaso = v_id_tipo_traspaso,
            motivo = BTRIM(p_motivo), fecha_requerida = p_fecha_requerida,
            actualizado_por = p_id_usuario, fecha_actualizacion = NOW()
        WHERE id_solicitud = v_id_solicitud AND id_empresa = p_id_empresa;

        DELETE FROM public.solicitud_traspaso_detalle
        WHERE id_solicitud = v_id_solicitud AND id_empresa = p_id_empresa;
    END IF;

    INSERT INTO public.solicitud_traspaso_detalle (
        id_empresa, id_solicitud, id_producto, id_unidad_medida, cantidad_solicitada
    )
    SELECT p_id_empresa, v_id_solicitud, item.id_producto, 1, item.cantidad
    FROM jsonb_to_recordset(p_productos)
        AS item(id_producto INTEGER, cantidad NUMERIC);

    RETURN QUERY SELECT v_id_solicitud, 'Borrador'::VARCHAR;
END;
$BODY$;

ALTER FUNCTION public.fn_guardar_borrador_solicitud_traspaso(bigint, integer, integer, integer, character varying, date, jsonb, integer)
    OWNER TO landiadm;


CREATE OR REPLACE FUNCTION public.confirmar_produccion_batida(
	p_orden bigint,
	p_centro integer,
	p_usuario integer,
	p_version integer,
	p_clave uuid)
    RETURNS jsonb
    LANGUAGE 'plpgsql'
    COST 100
    VOLATILE PARALLEL UNSAFE
AS $BODY$
DECLARE
  v_orden public.produccion_batida_ordenes%ROWTYPE;
  v_codigo varchar(20);
  v_item jsonb;
  v_config jsonb;
  v_consumo record;
  v_producto record;
  v_ubicacion record;
  v_stock_antes numeric;
  v_stock_despues numeric;
  v_kg_real numeric(12,3);
  v_lote varchar(80);
  v_lote_sufijo text;
  v_id_lote bigint;
  v_firmas integer;
BEGIN
  SELECT * INTO v_orden FROM public.produccion_batida_ordenes
  WHERE id = p_orden AND id_establecimiento = p_centro FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'La orden de batida no existe en esta sucursal' USING ERRCODE = 'P0002'; END IF;
  IF v_orden.estado = 'CONFIRMADA' THEN
    IF v_orden.clave_confirmacion IS DISTINCT FROM p_clave THEN
      RAISE EXCEPTION 'La batida ya fue confirmada' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object('id', v_orden.id, 'folio', v_orden.folio, 'estado', v_orden.estado,
      'kg_reales', v_orden.kg_reales, 'lote_interno', v_orden.lote_interno, 'duplicado', true);
  END IF;
  IF v_orden.estado <> 'BORRADOR' OR v_orden.version <> p_version THEN
    RAISE EXCEPTION 'El borrador cambió; vuelve a abrirlo' USING ERRCODE = '22023';
  END IF;
  IF v_orden.fecha_produccion > (now() AT TIME ZONE 'America/Mexico_City')::date THEN
    RAISE EXCEPTION 'La fecha programada de producción aún no llega' USING ERRCODE = '22023';
  END IF;
  SELECT e.codigo INTO v_codigo FROM public.cat_establecimientos e
  WHERE e.id = p_centro AND e.id_empresa = 1 AND e.enable = true AND upper(btrim(e.tipo)) = 'SUCURSAL';
  IF v_codigo IS NULL THEN RAISE EXCEPTION 'La sucursal no está disponible' USING ERRCODE = '22023'; END IF;

  SELECT count(*) INTO v_firmas FROM public.produccion_batida_firmas f
  WHERE f.id_orden = p_orden AND f.tipo IN ('CARNICERO', 'ENCARGADO');
  IF v_firmas <> 2 OR (SELECT count(DISTINCT lower(btrim(nombre_firmante))) FROM public.produccion_batida_firmas WHERE id_orden = p_orden) <> 2 THEN
    RAISE EXCEPTION 'Se requieren las firmas de dos personas distintas' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.produccion_batida_firmas WHERE id_orden = p_orden FOR SHARE;

  SELECT round(coalesce(sum(p.kg), 0), 3) INTO v_kg_real
  FROM public.produccion_batida_pesajes p WHERE p.id_orden = p_orden AND p.enable;
  IF v_kg_real <= 0 THEN RAISE EXCEPTION 'Registra el peso real del producto terminado' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM public.produccion_batida_pesajes p
    WHERE p.id_orden = p_orden AND p.enable AND p.metodo_pesaje = 'MANUAL' AND p.id_gerente_autoriza IS NULL) THEN
    RAISE EXCEPTION 'Hay pesajes manuales sin autorización' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_orden.insumos_verificados) <> 'array'
    OR jsonb_array_length(v_orden.insumos_verificados) <> jsonb_array_length(v_orden.configuracion->'insumos') THEN
    RAISE EXCEPTION 'Verifica todos los insumos antes de confirmar' USING ERRCODE = '22023';
  END IF;

  -- La fórmula sirve como referencia; la producción puede cerrarse con menos insumo
  -- del previsto. Se exige un consumo real positivo para cada ingrediente configurado.
  -- La función de descuento bloquea stock y lotes FIFO antes de consumir.
  FOR v_config IN SELECT item.value FROM jsonb_array_elements(v_orden.configuracion->'insumos') AS item(value) LOOP
    v_item := NULL;
    SELECT item.value INTO v_item FROM jsonb_array_elements(v_orden.insumos_verificados) AS item(value)
    WHERE (item.value->>'id_producto')::integer = (v_config->>'id_producto')::integer;
    IF v_item IS NULL OR (v_item->>'cantidad_kg')::numeric <= 0 THEN
      RAISE EXCEPTION 'El insumo % necesita una cantidad real positiva', v_config->>'nombre' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  FOR v_item IN SELECT item.value FROM jsonb_array_elements(v_orden.insumos_verificados) AS item(value) LOOP
    SELECT * INTO v_consumo FROM public.descontar_stock_producto(
      1, (v_item->>'id_producto')::bigint, NULL::varchar, v_codigo,
      (v_item->>'cantidad_kg')::numeric, 'PRODUCCION_BATIDA'::varchar, v_orden.folio::varchar);
    IF v_consumo.id_producto_stock IS DISTINCT FROM (v_item->>'id_producto')::bigint
      OR v_consumo.cantidad_stock IS DISTINCT FROM (v_item->>'cantidad_kg')::numeric
      OR v_consumo.stock_despues IS NULL THEN
      RAISE EXCEPTION 'El consumo no corresponde al insumo verificado %', v_item->>'id_producto' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  SELECT p.id, p.sku, p.nombre INTO STRICT v_producto FROM public.cat_productos p
  WHERE p.id = v_orden.id_producto_final AND p.id_empresa = 1 AND p.enable = true;
  INSERT INTO public.stock_sucursal (id_producto, sku, id_establecimiento, stock, stock_min, stock_max)
  VALUES (v_producto.id, v_producto.sku, v_codigo, 0, 0, 0)
  ON CONFLICT (id_producto, id_establecimiento) DO NOTHING;
  SELECT stock INTO v_stock_antes FROM public.stock_sucursal
  WHERE id_producto = v_producto.id AND id_establecimiento = v_codigo FOR UPDATE;

  SELECT u.id AS id_ubicacion, u.id_zona, z.id_almacen INTO v_ubicacion
  FROM (
    SELECT s.id_ubicacion, 0 AS prioridad, now() AS fecha, 0::bigint AS id
    FROM public.stock_sucursal s WHERE s.id_producto = v_producto.id
      AND s.id_establecimiento = v_codigo AND s.id_ubicacion IS NOT NULL
    UNION ALL
    SELECT l.id_ubicacion, 1, l.fecha_registro, l.id
    FROM public.stock_sucursal_lotes l WHERE l.id_empresa = 1 AND l.id_establecimiento = v_codigo
      AND (l.id_producto = v_producto.id OR l.id IN (
        SELECT cl.id_lote FROM public.stock_consumo_lote cl
        WHERE cl.id_empresa = 1 AND cl.id_establecimiento = v_codigo AND cl.referencia = v_orden.folio))
  ) ubicacion
  JOIN public.almacen_ubicaciones u ON u.id = ubicacion.id_ubicacion AND coalesce(u.enable, true)
  JOIN public.almacen_zonas z ON z.id = u.id_zona AND coalesce(z.enable, true)
  JOIN public.almacen a ON a.id = z.id_almacen AND coalesce(a.enable, true)
  JOIN public.cat_establecimientos e ON e.id = a.id_sucursal
  WHERE e.id_empresa = 1 AND e.codigo = v_codigo
  ORDER BY ubicacion.prioridad, ubicacion.fecha DESC, ubicacion.id DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'No hay ubicación de inventario válida para recibir el producto terminado' USING ERRCODE = '22023'; END IF;

  v_lote_sufijo := '-PRO-BT-' || p_orden::text || '-' ||
    to_char(now() AT TIME ZONE 'America/Mexico_City', 'YYYY-MM-DD-HH24-MI-SS');
  v_lote := rtrim(left(upper(trim(both '-' from regexp_replace(
    coalesce(nullif(trim(v_producto.sku), ''), v_producto.id::text), '[^A-Za-z0-9_-]+', '-', 'g'))),
    80 - length(v_lote_sufijo)), '-') || v_lote_sufijo;
  INSERT INTO public.stock_sucursal_lotes
    (id_empresa, id_producto, sku, id_establecimiento, id_almacen, id_zona, id_ubicacion,
     descripcion, lote_interno, unidad, cantidad, estado_existencia, referencia, evidencia)
  VALUES (1, v_producto.id, coalesce(v_producto.sku, v_producto.id::text), v_codigo,
    v_ubicacion.id_almacen, v_ubicacion.id_zona, v_ubicacion.id_ubicacion,
    left(v_producto.nombre, 500), v_lote, 'kg', v_kg_real, 'VENDIBLE', v_orden.folio,
    jsonb_build_object('origen', 'PRODUCCION', 'modalidad', 'BATIDA', 'id_orden', p_orden,
      'folio', v_orden.folio, 'fecha_produccion', v_orden.fecha_produccion, 'id_usuario', p_usuario))
  RETURNING id INTO v_id_lote;
  UPDATE public.stock_sucursal SET stock = stock + v_kg_real, fecha_modificacion = now()
  WHERE id_producto = v_producto.id AND id_establecimiento = v_codigo RETURNING stock INTO v_stock_despues;
  INSERT INTO public.stock_movimiento
    (id_empresa, id_producto_origen, id_producto_stock, id_establecimiento, cantidad_origen,
     cantidad_stock, tipo_movimiento, origen, referencia, stock_antes, stock_despues)
  VALUES (1, v_producto.id, v_producto.id, v_codigo, v_kg_real, v_kg_real,
    'ENTRADA', 'PRODUCCION_BATIDA', v_orden.folio, v_stock_antes, v_stock_despues);

  UPDATE public.produccion_batida_ordenes SET estado = 'CONFIRMADA', etapa = 'RESUMEN',
    kg_reales = v_kg_real, lote_interno = v_lote, id_lote_producto_final = v_id_lote,
    fecha_confirmacion = now(), confirmado_por = p_usuario, clave_confirmacion = p_clave,
    version = version + 1, modificado_por = p_usuario, fecha_modificacion = now()
  WHERE id = p_orden;
  RETURN jsonb_build_object('id', p_orden, 'folio', v_orden.folio, 'estado', 'CONFIRMADA',
    'kg_reales', v_kg_real, 'lote_interno', v_lote, 'id_lote_producto_final', v_id_lote, 'duplicado', false);
END;
$BODY$;

ALTER FUNCTION public.confirmar_produccion_batida(bigint, integer, integer, integer, uuid)
    OWNER TO landiadm;


CREATE OR REPLACE FUNCTION public.fn_confirmar_envio_transferencia(
	p_id_pedido bigint,
	p_id_empresa integer,
	p_id_sucursal_origen integer,
	p_id_usuario integer,
	p_idempotency_key character varying,
	p_productos jsonb)
    RETURNS TABLE(envio_id bigint, pedido_id bigint, pedido_folio character varying, pedido_estatus character varying, total_productos integer, cantidad_total numeric) 
    LANGUAGE 'plpgsql'
    COST 100
    VOLATILE PARALLEL UNSAFE
    ROWS 1000

AS $BODY$
DECLARE
  v_pedido public.pedidos_transferencia%ROWTYPE;
  v_envio public.pedido_transferencia_envios%ROWTYPE;
  v_codigo_sucursal VARCHAR;
  v_esperados INTEGER;
  v_recibidos INTEGER;
  v_coincidentes INTEGER;
  v_item RECORD;
  v_pesaje JSONB;
  v_lote RECORD;
  v_id_stock INTEGER;
  v_stock_antes NUMERIC(14,3);
  v_stock_despues NUMERIC(14,3);
  v_stock_reservado NUMERIC(14,3);
  v_stock_disponible NUMERIC(14,3);
  v_stock_lotes NUMERIC(14,3);
  v_cantidad NUMERIC(14,3);
  v_pendiente NUMERIC(14,3);
  v_descontar NUMERIC(14,3);
  v_id_envio_detalle BIGINT;
  v_total NUMERIC(14,3) := 0;
BEGIN
  IF NULLIF(BTRIM(COALESCE(p_idempotency_key, '')), '') IS NULL THEN
    RAISE EXCEPTION 'La clave de idempotencia es obligatoria';
  END IF;
  IF p_productos IS NULL OR jsonb_typeof(p_productos) <> 'array' OR jsonb_array_length(p_productos) = 0 THEN
    RAISE EXCEPTION 'Debes pesar todos los productos aceptados antes de confirmar el envío';
  END IF;

  SELECT * INTO v_pedido
  FROM public.pedidos_transferencia
  WHERE id_empresa = p_id_empresa AND id_pedido = p_id_pedido
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'El pedido de transferencia no existe'; END IF;
  IF v_pedido.id_sucursal_origen <> p_id_sucursal_origen THEN
    RAISE EXCEPTION 'El pedido no pertenece a la sucursal que realiza el envío';
  END IF;

  SELECT * INTO v_envio
  FROM public.pedido_transferencia_envios
  WHERE id_empresa = p_id_empresa AND id_pedido = p_id_pedido;
  IF FOUND THEN
    RETURN QUERY SELECT v_envio.id_envio, v_pedido.id_pedido, v_pedido.folio,
      v_pedido.estatus, v_envio.total_productos, v_envio.cantidad_total;
    RETURN;
  END IF;

  IF v_pedido.estatus NOT IN ('Aceptado', 'Listo para pick') THEN
    RAISE EXCEPTION 'El pedido no está disponible para confirmar su envío';
  END IF;

  SELECT codigo::VARCHAR INTO v_codigo_sucursal
  FROM public.cat_establecimientos
  WHERE id_empresa = p_id_empresa AND id = p_id_sucursal_origen AND enable = TRUE;
  IF v_codigo_sucursal IS NULL THEN RAISE EXCEPTION 'La sucursal de origen no está disponible'; END IF;

  SELECT COUNT(*)::INTEGER INTO v_esperados
  FROM public.pedido_transferencia_detalle
  WHERE id_empresa = p_id_empresa AND id_pedido = p_id_pedido
    AND respuesta IN ('Aceptar', 'Modificar') AND COALESCE(cantidad_confirmada, 0) > 0;

  SELECT COUNT(*)::INTEGER,
         COUNT(DISTINCT NULLIF(item.value->>'id_pedido_detalle', '')::BIGINT)::INTEGER
    INTO v_recibidos, v_coincidentes
  FROM jsonb_array_elements(p_productos) item;
  IF v_recibidos <> v_esperados OR v_coincidentes <> v_esperados THEN
    RAISE EXCEPTION 'Debes pesar exactamente los % productos aceptados del pedido', v_esperados;
  END IF;

  SELECT COUNT(*)::INTEGER INTO v_coincidentes
  FROM public.pedido_transferencia_detalle detalle
  WHERE detalle.id_empresa = p_id_empresa AND detalle.id_pedido = p_id_pedido
    AND detalle.respuesta IN ('Aceptar', 'Modificar') AND COALESCE(detalle.cantidad_confirmada, 0) > 0
    AND detalle.id_pedido_detalle IN (
      SELECT NULLIF(item.value->>'id_pedido_detalle', '')::BIGINT FROM jsonb_array_elements(p_productos) item
    );
  IF v_coincidentes <> v_esperados THEN RAISE EXCEPTION 'La lista de productos pesados no corresponde al pedido'; END IF;

  INSERT INTO public.pedido_transferencia_envios (
    id_empresa, id_pedido, id_sucursal_origen, id_sucursal_destino,
    id_usuario, idempotency_key, total_productos
  ) VALUES (
    p_id_empresa, p_id_pedido, p_id_sucursal_origen, v_pedido.id_sucursal_destino,
    p_id_usuario, BTRIM(p_idempotency_key), v_esperados
  ) RETURNING * INTO v_envio;

  FOR v_item IN
    SELECT detalle.id_pedido_detalle, detalle.cantidad_confirmada,
           solicitud_detalle.id_producto, item.value AS payload
    FROM jsonb_array_elements(p_productos) item
    JOIN public.pedido_transferencia_detalle detalle
      ON detalle.id_pedido_detalle = NULLIF(item.value->>'id_pedido_detalle', '')::BIGINT
     AND detalle.id_empresa = p_id_empresa AND detalle.id_pedido = p_id_pedido
    JOIN public.solicitud_traspaso_detalle solicitud_detalle
      ON solicitud_detalle.id_solicitud_detalle = detalle.id_solicitud_detalle
     AND solicitud_detalle.id_empresa = detalle.id_empresa
    ORDER BY detalle.id_pedido_detalle
  LOOP
    IF jsonb_typeof(COALESCE(v_item.payload->'pesajes', '[]'::JSONB)) <> 'array'
       OR jsonb_array_length(COALESCE(v_item.payload->'pesajes', '[]'::JSONB)) = 0 THEN
      RAISE EXCEPTION 'Falta pesar uno de los productos del pedido';
    END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_item.payload->'pesajes') peso
      WHERE COALESCE(NULLIF(peso.value->>'cantidad', '')::NUMERIC, 0) <= 0
    ) THEN RAISE EXCEPTION 'Todos los pesajes deben ser mayores a cero'; END IF;

    SELECT ROUND(SUM((peso.value->>'cantidad')::NUMERIC), 3)
      INTO v_cantidad
    FROM jsonb_array_elements(v_item.payload->'pesajes') peso;
    IF v_cantidad > v_item.cantidad_confirmada + 0.000001 THEN
      RAISE EXCEPTION 'El peso enviado (%) no puede superar la cantidad aceptada (%)',
        v_cantidad, v_item.cantidad_confirmada;
    END IF;

    SELECT s.id, s.stock::NUMERIC(14,3), COALESCE((
      SELECT SUM(linea.cantidad_reservada)::NUMERIC(14,3)
      FROM public.preorden_linea linea
      JOIN public.preorden_cabecera preorden ON preorden.id = linea.id_preorden AND preorden.enable = 1
      WHERE linea.enable = 1 AND preorden.estatus = 'CONFIRMADA'
        AND preorden.fecha_hora_programada >= timezone('America/Mexico_City', now()) - interval '2 hours'
        AND linea.id_producto = v_item.id_producto
        AND preorden.codigo_establecimiento = v_codigo_sucursal
    ), 0)::NUMERIC(14,3)
      INTO v_id_stock, v_stock_antes, v_stock_reservado
    FROM public.stock_sucursal s
    WHERE s.id_producto = v_item.id_producto AND s.id_establecimiento = v_codigo_sucursal
    ORDER BY s.id LIMIT 1 FOR UPDATE;
    IF v_id_stock IS NULL THEN RAISE EXCEPTION 'No existe inventario para el producto % en la sucursal', v_item.id_producto; END IF;

    v_stock_disponible := GREATEST(v_stock_antes - v_stock_reservado, 0);
    IF v_stock_disponible + 0.000001 < v_cantidad THEN
      RAISE EXCEPTION 'Stock insuficiente para el producto %. Disponible: %, pesado: %',
        v_item.id_producto, v_stock_disponible, v_cantidad;
    END IF;

    PERFORM id FROM public.stock_sucursal_lotes
    WHERE id_empresa = p_id_empresa AND id_producto = v_item.id_producto
      AND id_establecimiento = v_codigo_sucursal
      AND COALESCE(estado_existencia, 'VENDIBLE') = 'VENDIBLE' AND cantidad > 0
    ORDER BY fecha_registro, id FOR UPDATE;
    SELECT COALESCE(SUM(cantidad), 0)::NUMERIC(14,3) INTO v_stock_lotes
    FROM public.stock_sucursal_lotes
    WHERE id_empresa = p_id_empresa AND id_producto = v_item.id_producto
      AND id_establecimiento = v_codigo_sucursal
      AND COALESCE(estado_existencia, 'VENDIBLE') = 'VENDIBLE' AND cantidad > 0;
    IF v_stock_lotes + 0.000001 < v_cantidad THEN
      RAISE EXCEPTION 'Los lotes vendibles del producto % no cubren el peso enviado. Disponible: %, pesado: %',
        v_item.id_producto, v_stock_lotes, v_cantidad;
    END IF;

    UPDATE public.stock_sucursal
    SET stock = ROUND((stock - v_cantidad)::NUMERIC, 3), fecha_modificacion = NOW()
    WHERE id = v_id_stock RETURNING stock::NUMERIC(14,3) INTO v_stock_despues;

    INSERT INTO public.pedido_transferencia_envio_detalle (
      id_envio, id_empresa, id_pedido_detalle, id_producto,
      cantidad_aceptada, cantidad_enviada, stock_antes, stock_despues
    ) VALUES (
      v_envio.id_envio, p_id_empresa, v_item.id_pedido_detalle, v_item.id_producto,
      v_item.cantidad_confirmada, v_cantidad, v_stock_antes, v_stock_despues
    ) RETURNING id_envio_detalle INTO v_id_envio_detalle;

    v_pendiente := v_cantidad;
    FOR v_lote IN
      SELECT id, cantidad, sku, descripcion, lote_interno, lote_proveedor,
             unidad, fecha_caducidad, fecha_registro
      FROM public.stock_sucursal_lotes
      WHERE id_empresa = p_id_empresa AND id_producto = v_item.id_producto
        AND id_establecimiento = v_codigo_sucursal
        AND COALESCE(estado_existencia, 'VENDIBLE') = 'VENDIBLE' AND cantidad > 0
      ORDER BY fecha_registro, id FOR UPDATE
    LOOP
      EXIT WHEN v_pendiente <= 0;
      v_descontar := LEAST(v_lote.cantidad, v_pendiente);
      UPDATE public.stock_sucursal_lotes SET cantidad = cantidad - v_descontar WHERE id = v_lote.id;
      INSERT INTO public.stock_consumo_lote (
        id_empresa, id_producto_origen, id_producto_stock, id_establecimiento, referencia, id_lote, cantidad
      ) VALUES (
        p_id_empresa, v_item.id_producto, v_item.id_producto, v_codigo_sucursal,
        v_pedido.folio, v_lote.id, v_descontar
      );
      INSERT INTO public.pedido_transferencia_envio_lotes (
        id_envio_detalle, id_lote_origen, cantidad, sku, descripcion,
        lote_interno, lote_proveedor, unidad, fecha_caducidad, fecha_lote_origen
      ) VALUES (
        v_id_envio_detalle, v_lote.id, v_descontar, v_lote.sku, v_lote.descripcion,
        v_lote.lote_interno, v_lote.lote_proveedor, v_lote.unidad,
        v_lote.fecha_caducidad, v_lote.fecha_registro
      );
      v_pendiente := v_pendiente - v_descontar;
    END LOOP;

    INSERT INTO public.stock_movimiento (
      id_empresa, id_producto_origen, id_producto_stock, id_establecimiento,
      cantidad_origen, cantidad_stock, tipo_movimiento, origen, referencia,
      stock_antes, stock_despues
    ) VALUES (
      p_id_empresa, v_item.id_producto, v_item.id_producto, v_codigo_sucursal,
      v_cantidad, v_cantidad, 'SALIDA', 'TRANSFERENCIA', v_pedido.folio,
      v_stock_antes, v_stock_despues
    );

    FOR v_pesaje IN SELECT value FROM jsonb_array_elements(v_item.payload->'pesajes')
    LOOP
      INSERT INTO public.pedido_transferencia_envio_pesajes (
        id_envio_detalle, cantidad, origen_peso, metodo_pesaje, bascula, lectura_bascula, fecha_pesaje
      ) VALUES (
        v_id_envio_detalle, ROUND((v_pesaje->>'cantidad')::NUMERIC, 3),
        NULLIF(v_pesaje->>'origen_peso', '')::SMALLINT,
        NULLIF(BTRIM(v_pesaje->>'metodo_pesaje'), ''),
        v_pesaje->'bascula', v_pesaje->'lectura_bascula',
        COALESCE(NULLIF(v_pesaje->>'fecha', '')::TIMESTAMPTZ, NOW())
      );
    END LOOP;
    v_total := v_total + v_cantidad;
  END LOOP;

  UPDATE public.pedido_transferencia_envios
  SET cantidad_total = ROUND(v_total, 3) WHERE id_envio = v_envio.id_envio;
  UPDATE public.pedidos_transferencia SET estatus = 'Enviado' WHERE id_pedido = p_id_pedido;

  RETURN QUERY SELECT v_envio.id_envio, v_pedido.id_pedido, v_pedido.folio,
    'Enviado'::VARCHAR, v_esperados, ROUND(v_total, 3);
END;
$BODY$;

ALTER FUNCTION public.fn_confirmar_envio_transferencia(bigint, integer, integer, integer, character varying, jsonb)
    OWNER TO landiadm;


CREATE OR REPLACE FUNCTION public.fn_responder_pedido_transferencia(
	p_id_pedido bigint,
	p_id_empresa integer,
	p_id_sucursal_origen integer,
	p_id_usuario integer,
	p_respuestas jsonb)
    RETURNS TABLE(pedido_id bigint, pedido_folio character varying, pedido_estatus character varying, solicitud_id bigint) 
    LANGUAGE 'plpgsql'
    COST 100
    VOLATILE PARALLEL UNSAFE
    ROWS 1000

AS $BODY$
DECLARE
    v_pedido public.pedidos_transferencia%ROWTYPE;
    v_total_detalles INTEGER;
    v_estatus VARCHAR(20);
BEGIN
    SELECT * INTO v_pedido
    FROM public.pedidos_transferencia p
    WHERE p.id_pedido = p_id_pedido
      AND p.id_empresa = p_id_empresa
      AND p.id_sucursal_origen = p_id_sucursal_origen
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El pedido no existe o no pertenece a la sucursal activa';
    END IF;
    IF v_pedido.estatus <> 'Pendiente' THEN
        RAISE EXCEPTION 'El pedido ya fue respondido y no puede modificarse';
    END IF;
    PERFORM 1
    FROM public.solicitudes_traspaso st
    WHERE st.id_empresa = p_id_empresa
      AND st.id_solicitud = v_pedido.id_solicitud
    FOR UPDATE;
    IF p_respuestas IS NULL OR jsonb_typeof(p_respuestas) <> 'array'
       OR jsonb_array_length(p_respuestas) = 0 THEN
        RAISE EXCEPTION 'Captura la respuesta de todos los productos del pedido';
    END IF;

    SELECT COUNT(*) INTO v_total_detalles
    FROM public.pedido_transferencia_detalle pd
    WHERE pd.id_empresa = p_id_empresa
      AND pd.id_pedido = p_id_pedido;

    IF jsonb_array_length(p_respuestas) <> v_total_detalles THEN
        RAISE EXCEPTION 'Debes responder todos los productos del pedido';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_respuestas) AS r(
            id_pedido_detalle BIGINT,
            respuesta VARCHAR,
            cantidad_confirmada NUMERIC,
            justificacion VARCHAR
        )
        GROUP BY r.id_pedido_detalle
        HAVING r.id_pedido_detalle IS NULL OR COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Las respuestas contienen productos duplicados o invalidos';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_respuestas) AS r(
            id_pedido_detalle BIGINT,
            respuesta VARCHAR,
            cantidad_confirmada NUMERIC,
            justificacion VARCHAR
        )
        LEFT JOIN public.pedido_transferencia_detalle pd
          ON pd.id_pedido_detalle = r.id_pedido_detalle
         AND pd.id_pedido = p_id_pedido
         AND pd.id_empresa = p_id_empresa
        WHERE pd.id_pedido_detalle IS NULL
           OR r.respuesta IS NULL
           OR r.respuesta NOT IN ('Aceptar', 'Modificar', 'Rechazar')
           OR (r.respuesta = 'Modificar' AND (
               r.cantidad_confirmada IS NULL
               OR r.cantidad_confirmada <= 0
               OR r.cantidad_confirmada >= pd.cantidad_solicitada
           ))
           OR (r.respuesta = 'Rechazar' AND NULLIF(BTRIM(r.justificacion), '') IS NULL)
           OR CHAR_LENGTH(COALESCE(r.justificacion, '')) > 250
    ) THEN
        RAISE EXCEPTION 'Una o mas respuestas no cumplen las reglas del pedido';
    END IF;

    UPDATE public.pedido_transferencia_detalle pd
    SET respuesta = r.respuesta,
        cantidad_confirmada = CASE
            WHEN r.respuesta = 'Aceptar' THEN pd.cantidad_solicitada
            WHEN r.respuesta = 'Modificar' THEN r.cantidad_confirmada
            ELSE 0
        END,
        justificacion_rechazo = CASE
            WHEN r.respuesta = 'Rechazar' THEN BTRIM(r.justificacion)
            ELSE NULL
        END
    FROM jsonb_to_recordset(p_respuestas) AS r(
        id_pedido_detalle BIGINT,
        respuesta VARCHAR,
        cantidad_confirmada NUMERIC,
        justificacion VARCHAR
    )
    WHERE pd.id_pedido_detalle = r.id_pedido_detalle
      AND pd.id_pedido = p_id_pedido
      AND pd.id_empresa = p_id_empresa;

    SELECT CASE
        WHEN BOOL_OR(r.respuesta IN ('Aceptar', 'Modificar')) THEN 'Aceptado'
        ELSE 'Rechazado'
    END INTO v_estatus
    FROM jsonb_to_recordset(p_respuestas) AS r(
        id_pedido_detalle BIGINT,
        respuesta VARCHAR,
        cantidad_confirmada NUMERIC,
        justificacion VARCHAR
    );

    UPDATE public.pedidos_transferencia
    SET estatus = v_estatus,
        fecha_respuesta = NOW(),
        respondido_por = p_id_usuario
    WHERE id_pedido = p_id_pedido
      AND id_empresa = p_id_empresa;

    UPDATE public.solicitudes_traspaso st
    SET estatus = CASE
            WHEN EXISTS (
                SELECT 1
                FROM public.vw_solicitud_detalle_progreso progreso
                WHERE progreso.id_empresa = p_id_empresa
                  AND progreso.id_solicitud = v_pedido.id_solicitud
                  AND progreso.cantidad_pendiente_asignar > 0
            ) THEN 'Parcialmente asignada'
            ELSE 'Asignada'
        END,
        actualizado_por = p_id_usuario,
        fecha_actualizacion = NOW()
    WHERE st.id_empresa = p_id_empresa
      AND st.id_solicitud = v_pedido.id_solicitud;

    pedido_id := v_pedido.id_pedido;
    pedido_folio := v_pedido.folio;
    pedido_estatus := v_estatus;
    solicitud_id := v_pedido.id_solicitud;
    RETURN NEXT;
END;
$BODY$;

ALTER FUNCTION public.fn_responder_pedido_transferencia(bigint, integer, integer, integer, jsonb)
    OWNER TO landiadm;


CREATE OR REPLACE FUNCTION public.fn_asignar_solicitud_traspaso(
	p_id_solicitud bigint,
	p_id_empresa integer,
	p_id_usuario integer,
	p_asignaciones jsonb)
    RETURNS TABLE(pedido_id bigint, pedido_folio character varying, id_sucursal_origen integer) 
    LANGUAGE 'plpgsql'
    COST 100
    VOLATILE PARALLEL UNSAFE
    ROWS 1000

AS $BODY$
DECLARE
    v_solicitud public.solicitudes_traspaso%ROWTYPE;
    v_id_sucursal_origen INTEGER;
    v_id_pedido BIGINT;
    v_folio VARCHAR(40);
BEGIN
    SELECT * INTO v_solicitud
    FROM public.solicitudes_traspaso st
    WHERE st.id_solicitud = p_id_solicitud
      AND st.id_empresa = p_id_empresa
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La solicitud no existe o pertenece a otra empresa';
    END IF;
    IF v_solicitud.estatus NOT IN ('Enviada', 'En revision', 'Parcialmente asignada') THEN
        RAISE EXCEPTION 'La solicitud ya no esta disponible para asignacion';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM public.cat_usuarios u
        WHERE u.id = p_id_usuario
          AND u.enable = TRUE
          AND (
              COALESCE(u.isadmin, FALSE) = TRUE
              OR (
                  EXISTS (
                      SELECT 1
                      FROM public.cat_usuario_accesos ua
                      JOIN public.cat_sistemas_acceso sa
                        ON sa.id = ua.id_sistema_acceso
                       AND sa.enable = TRUE
                       AND sa.codigo = 'WEB'
                      WHERE ua.id_usuario = u.id
                        AND ua.id_empresa = p_id_empresa
                        AND ua.enable = TRUE
                  )
                  AND EXISTS (
                      SELECT 1
                      FROM public.cat_empleados e
                      JOIN public.cat_puestos p
                        ON p.id = e.id_puesto
                       AND p.enable = TRUE
                      JOIN public.permisos_puesto_sidebar permiso
                        ON permiso.id_puesto = e.id_puesto
                       AND permiso.id_empresa = p_id_empresa
                       AND permiso.sidebar_key = 'traspasos_solicitud'
                       AND permiso.permitido = TRUE
                      WHERE e.id = u.id_empleado
                        AND e.enable = TRUE
                  )
              )
          )
    ) THEN
        RAISE EXCEPTION 'El usuario no tiene permiso activo para asignar solicitudes de traspaso en esta empresa';
    END IF;
    IF p_asignaciones IS NULL OR jsonb_typeof(p_asignaciones) <> 'array'
       OR jsonb_array_length(p_asignaciones) = 0 THEN
        RAISE EXCEPTION 'Agrega al menos una asignacion';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_asignaciones) AS a(
            id_solicitud_detalle BIGINT,
            id_sucursal_origen INTEGER,
            cantidad NUMERIC
        )
        WHERE a.id_solicitud_detalle IS NULL OR a.id_solicitud_detalle <= 0
           OR a.id_sucursal_origen IS NULL OR a.id_sucursal_origen <= 0
           OR a.cantidad IS NULL OR a.cantidad <= 0
    ) THEN
        RAISE EXCEPTION 'Las asignaciones contienen datos invalidos';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_asignaciones) AS a(
            id_solicitud_detalle BIGINT,
            id_sucursal_origen INTEGER,
            cantidad NUMERIC
        )
        GROUP BY a.id_solicitud_detalle, a.id_sucursal_origen
        HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'No se permiten asignaciones duplicadas';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_asignaciones) AS a(
            id_solicitud_detalle BIGINT,
            id_sucursal_origen INTEGER,
            cantidad NUMERIC
        )
        LEFT JOIN public.solicitud_traspaso_detalle d
          ON d.id_solicitud_detalle = a.id_solicitud_detalle
         AND d.id_solicitud = p_id_solicitud
         AND d.id_empresa = p_id_empresa
        WHERE d.id_solicitud_detalle IS NULL
    ) THEN
        RAISE EXCEPTION 'Uno de los productos no pertenece a la solicitud';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM public.vw_solicitud_detalle_progreso progreso
        LEFT JOIN (
            SELECT a.id_solicitud_detalle, SUM(a.cantidad) AS cantidad_asignada
            FROM jsonb_to_recordset(p_asignaciones) AS a(
                id_solicitud_detalle BIGINT,
                id_sucursal_origen INTEGER,
                cantidad NUMERIC
            )
            GROUP BY a.id_solicitud_detalle
        ) asignado ON asignado.id_solicitud_detalle = progreso.id_solicitud_detalle
        WHERE progreso.id_solicitud = p_id_solicitud
          AND progreso.id_empresa = p_id_empresa
          AND COALESCE(asignado.cantidad_asignada, 0) <> progreso.cantidad_pendiente_asignar
    ) THEN
        RAISE EXCEPTION 'Todos los faltantes deben quedar asignados por la cantidad pendiente';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_asignaciones) AS a(
            id_solicitud_detalle BIGINT,
            id_sucursal_origen INTEGER,
            cantidad NUMERIC
        )
        LEFT JOIN public.cat_establecimientos e
          ON e.id = a.id_sucursal_origen
         AND e.id_empresa = p_id_empresa
         AND e.enable = TRUE
         AND (
             e.es_punto_venta = TRUE
             OR UPPER(BTRIM(COALESCE(e.tipo, ''))) = 'CEDIS'
         )
        WHERE e.id IS NULL
           OR e.id = v_solicitud.id_sucursal_solicitante
    ) THEN
        RAISE EXCEPTION 'Una sucursal de origen no esta disponible';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_asignaciones) AS a(
            id_solicitud_detalle BIGINT,
            id_sucursal_origen INTEGER,
            cantidad NUMERIC
        )
        JOIN public.solicitud_traspaso_detalle d
          ON d.id_solicitud_detalle = a.id_solicitud_detalle
         AND d.id_solicitud = p_id_solicitud
         AND d.id_empresa = p_id_empresa
        JOIN public.cat_establecimientos e
          ON e.id = a.id_sucursal_origen
         AND e.id_empresa = p_id_empresa
        WHERE a.cantidad > (
            SELECT COALESCE(SUM(s.stock), 0)
            FROM public.stock_sucursal s
            WHERE s.id_producto = d.id_producto
              AND s.id_establecimiento::TEXT IN (e.codigo::TEXT, e.id::TEXT)
        )
    ) THEN
        RAISE EXCEPTION 'Una asignacion supera la existencia disponible';
    END IF;

    FOR v_id_sucursal_origen IN
        SELECT DISTINCT a.id_sucursal_origen
        FROM jsonb_to_recordset(p_asignaciones) AS a(
            id_solicitud_detalle BIGINT,
            id_sucursal_origen INTEGER,
            cantidad NUMERIC
        )
        ORDER BY a.id_sucursal_origen
    LOOP
        v_folio := public.fn_traspaso_generar_folio(
            'PT', p_id_empresa, v_id_sucursal_origen
        );

        INSERT INTO public.pedidos_transferencia (
            id_empresa, folio, id_solicitud, id_sucursal_origen,
            id_sucursal_destino, estatus, prioridad
        ) VALUES (
            p_id_empresa, v_folio, p_id_solicitud, v_id_sucursal_origen,
            v_solicitud.id_sucursal_solicitante, 'Pendiente', 'Normal'
        ) RETURNING id_pedido INTO v_id_pedido;

        INSERT INTO public.pedido_transferencia_detalle (
            id_empresa, id_pedido, id_solicitud_detalle, cantidad_solicitada
        )
        SELECT p_id_empresa, v_id_pedido, a.id_solicitud_detalle, a.cantidad
        FROM jsonb_to_recordset(p_asignaciones) AS a(
            id_solicitud_detalle BIGINT,
            id_sucursal_origen INTEGER,
            cantidad NUMERIC
        )
        WHERE a.id_sucursal_origen = v_id_sucursal_origen;

        pedido_id := v_id_pedido;
        pedido_folio := v_folio;
        id_sucursal_origen := v_id_sucursal_origen;
        RETURN NEXT;
    END LOOP;

    UPDATE public.solicitudes_traspaso
    SET estatus = 'Asignada',
        actualizado_por = p_id_usuario,
        fecha_actualizacion = NOW()
    WHERE id_solicitud = p_id_solicitud
      AND id_empresa = p_id_empresa;
END;
$BODY$;

ALTER FUNCTION public.fn_asignar_solicitud_traspaso(bigint, integer, integer, jsonb)
    OWNER TO landiadm;



 END;

 -- only target

 DROP FUNCTION IF EXISTS public.fn_guardar_borrador_solicitud_traspaso(p_id_solicitud bigint, p_id_empresa integer, p_id_usuario integer, p_id_sucursal integer, p_motivo character varying, p_fecha_requerida date, p_productos jsonb);
